// src/core/keymap.js
// Maps multi-key sequences (e.g. "gg", "gh") to actions and resolves them one
// key at a time. An exact match wins over a shorter prefix.
function createKeymap(bindings = {}) {
  const map = new Map(Object.entries(bindings));
  const prefixes = new Set();
  for (const sequence of map.keys()) {
    for (let length = 1; length < sequence.length; length += 1) {
      prefixes.add(sequence.slice(0, length));
    }
  }
  let pending = '';

  return {
    pending() {
      return pending;
    },
    reset() {
      pending = '';
    },
    press(key) {
      const candidate = pending + key;
      if (map.has(candidate)) {
        pending = '';
        map.get(candidate)();
        return { status: 'match', sequence: candidate };
      }
      if (prefixes.has(candidate)) {
        pending = candidate;
        return { status: 'prefix', sequence: candidate };
      }
      pending = '';
      return { status: 'none', sequence: candidate };
    },
  };
}

// src/core/pages.js
const LEGACY_PAGE = /\.php$/i;

function parseTarget(href) {
  if (typeof href !== 'string' || href === '') return null;
  let url;
  try {
    url = new URL(href, 'https://zabbix.invalid/');
  } catch {
    return null;
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;

  const action = url.searchParams.get('action');
  if (action) return { kind: 'action', name: action, href: url.href };

  const file = url.pathname.split('/').filter(Boolean).pop() || '';
  if (LEGACY_PAGE.test(file)) return { kind: 'page', name: file.toLowerCase(), href: url.href };

  return null;
}

function findActionTarget(anchors, wanted) {
  const needle = String(wanted).toLowerCase();
  const exact = [];
  const partial = [];
  for (const anchor of anchors) {
    const target = parseTarget(anchor.href);
    if (!target) continue;
    const name = target.name.toLowerCase();
    if (name === needle) exact.push(anchor);
    else if (name.includes(needle)) partial.push(anchor);
  }
  return exact[0] || partial[0] || null;
}

